package com.mjentertainment.mjplay.android

import java.io.IOException
import org.junit.Assert.*
import org.junit.Test

class PreparedLivePlaylistProofTest {
    // Generated by Node WebCrypto AES-CTR, length64, synthetic URL/key/sequence only.
    private val key = ByteArray(16) { it.toByte() }
    @Test fun webCryptoFixtureMatchesNativePreparation() {
        val raw = "#EXTM3U\n#EXT-X-MEDIA-SEQUENCE:122773\n#EXTINF:6,\nPiL2waqsmskSmIEW2KvC4f2GzRuRH7vU\n#EXTINF:6,\n5Z7cRIML4IgdF1PyoZZ0hWzLqDLvCn05\n"
        val prepared = PreparedLivePlaylistProof.prepare(raw, key) { it.host == "cdn.example" }
        assertTrue(prepared.contains("https://cdn.example/a.ts\n"))
        assertTrue(prepared.contains("https://cdn.example/b.ts\n"))
    }
    @Test fun wrongSequenceAndUnapprovedHostAreRejected() {
        val raw = "#EXTM3U\n#EXT-X-MEDIA-SEQUENCE:122773\nPiL2waqsmskSmIEW2KvC4f2GzRuRH7vU\n"
        assertThrows(IOException::class.java) { PreparedLivePlaylistProof.prepare(raw.replace("122773", "122774"), key) { true } }
        assertThrows(IOException::class.java) { PreparedLivePlaylistProof.prepare(raw, key) { false } }
        assertThrows(IOException::class.java) { PreparedLivePlaylistProof.prepare(raw.replace("#EXT-X-MEDIA-SEQUENCE:122773\n", ""), key) { true } }
    }
}
